import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringBuilder sbInput = new StringBuilder();
        String line;
        while ((line = br.readLine()) != null) {
            sbInput.append(line).append(' ');
        }

        StringTokenizer st = new StringTokenizer(sbInput.toString());
        int n = Integer.parseInt(st.nextToken());

        int[] a = new int[n];
        for (int i = 0; i < n; i++) {
            a[i] = Integer.parseInt(st.nextToken());
        }

        final long INF = Long.MAX_VALUE / 4;
        long[] left = new long[n];

        long best = INF;
        for (int i = 0; i < n; i++) {
            if (a[i] != -1) {
                best = Math.min(best, (long) a[i] - i);
            }
            if (best != INF) {
                left[i] = best + i;
            } else {
                left[i] = INF;
            }
        }

        long[] ans = new long[n];
        best = INF;

        for (int i = n - 1; i >= 0; i--) {
            if (a[i] != -1) {
                best = Math.min(best, (long) a[i] + i);
            }
            long right = (best == INF) ? INF : best - i;
            ans[i] = Math.min(left[i], right);
        }

        StringBuilder out = new StringBuilder();
        for (int i = 0; i < n; i++) {
            if (i > 0) out.append(' ');
            out.append(ans[i]);
        }
        out.append('\n');

        System.out.print(out.toString());
    }
}
